        B_shared = T.alloc_shared([32, 32], dtype="float16")
        C_local = T.alloc_local([32, 32], dtype="float32")

        C_local[...] = 0.0

        for k in T.serial(T.ceildiv(K, 32)):
            # Load A into shared memory
            for i in T.serial(32):
                for j in T.serial(32):
                    if (ty * 32 + i < M) and (k * 32 + j < K):
